// Kumbra post components (from the Instagram pieces). Every function returns HTML at 1080px scale.
const Q=new URLSearchParams(''),V='pre';
// ---------- brand ----------
const GRAD=`<linearGradient id="LG" x1="0" y1="220" x2="0" y2="820" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#F2B44A"/><stop offset=".22" stop-color="#F08A3C"/><stop offset=".42" stop-color="#E5484D"/><stop offset=".62" stop-color="#A7377B"/><stop offset=".82" stop-color="#533794"/><stop offset="1" stop-color="#382562"/></linearGradient>`;
let LGN=0;
const LOGO=h=>{const id='lg'+(LGN++);return `<svg height="${h}" viewBox="128 208 768 616"><defs>${GRAD.replace('id="LG"',`id="${id}"`)}</defs><path d="M139.59,820 Q355.59,628 512,220 Q668.41,628 884.41,820 Z" fill="url(#${id})"/><path d="M427.11,416.59 L512,220 L596.89,416.59 L549.35,380.38 L515.40,431.07 L478.04,385.81 Z" fill="#fff"/></svg>`};
const head=(bg,n)=>`<div class="hd"><div class="brand">${bg==='cream'?`<div class="ico">${LOGO(30)}</div>`:LOGO(44)}kumbra</div><span class="n">${n||''}</span></div>`;
const P=(bg,n,body)=>`<div class="p ${bg}">${head(bg,n)}${body}</div>`;
// ---------- grades ----------
const GC={'4':'#3DB36B','5':'#3DB36B','5+':'#3DB36B','6A':'#E8C23A','6A+':'#E8C23A','6B':'#F08A3C','6B+':'#F08A3C','6C':'#E5484D','6C+':'#E5484D','7A':'#D0479A','7A+':'#D0479A','7B':'#8B5CF6','7B+':'#8B5CF6','7C':'#5B6CF0','7C+':'#5B6CF0','8A':'#5B6CF0'};
const ORDER=['4','5','5+','6A','6A+','6B','6B+','6C','6C+','7A','7A+','7B','7B+','7C','7C+','8A'];
const lvl=g=>ORDER.indexOf(g);
function mix(hex,k,to=255){const n=parseInt(hex.slice(1),16);const f=v=>Math.round(v+(to-v)*k).toString(16).padStart(2,'0');return '#'+f(n>>16&255)+f(n>>8&255)+f(n&255)}
let RN=0;
// list: [{g,f(flash),p(project)}]; app-style ridge on a fixed scale 4..7C
function ridge(list,w,h,o={}){
  const id='r'+(RN++),n=list.length,pad=o.pad??w*.07,padR=o.padR??pad,sp=(w-pad-padR)/Math.max(n-1,1),hw=o.hw??sp*1.15,top=o.top??60,base=h-(o.bottom??0),dark=o.light?null:'#141216';
  const yOf=g=>base-(.2+.8*(lvl(g)/(ORDER.length-3)))*(base-top);
  let defs='',body='';
  if(o.grid!==false){['6A','6C','7B'].forEach(g=>{const y=yOf(g);body+=`<line x1="${pad*.4}" x2="${w-78}" y1="${y}" y2="${y}" stroke="${o.light?'#00000022':'#ffffff22'}" stroke-width="2" stroke-dasharray="6 10"/><text x="${w-22}" y="${y+9}" text-anchor="end" font-family="I" font-weight="600" font-size="24" fill="${o.light?'#00000066':'#ffffff6a'}">${g}</text>`})}
  const pk=list.map((a,i)=>({...a,x:pad+sp*i,y:yOf(a.g),c:GC[a.g],i}));
  // draw projects first (behind), then sends from back to front left→right so overlaps read like the app
  const ord=pk.filter(p=>p.p).concat(pk.filter(p=>!p.p));
  ord.forEach(p=>{const ph=base-p.y,gid=id+'g'+p.i;
    const fl=(t,left)=>{const sx=left?p.x-hw:p.x+hw,cx=left?p.x-hw*.42:p.x+hw*.42,cy=base-ph*.32,u=1-t;return [u*u*sx+2*u*t*cx+t*t*p.x,u*u*base+2*u*t*cy+t*t*p.y]};
    const d=`M${p.x-hw},${base} Q${p.x-hw*.42},${base-ph*.32} ${p.x},${p.y} Q${p.x+hw*.42},${base-ph*.32} ${p.x+hw},${base}`;
    if(p.p){body+=`<path d="${d} Z" fill="${p.c}" opacity="${o.light?.25:.2}"/>`;return}
    defs+=`<linearGradient id="${gid}" x1="0" y1="${p.y}" x2="0" y2="${base}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${p.c}"/><stop offset="1" stop-color="${dark?mix(p.c,.38,20):mix(p.c,.12,20)}"/></linearGradient>`;
    body+=`<path d="${d} Z" fill="url(#${gid})"/>`;
    if(p.f){const depth=ph*.26,t=1-depth/ph,a=fl(t,true),b=fl(t,false),ww=b[0]-a[0],jag=depth*.25;
      body+=`<path d="M${a[0]},${a[1]} L${p.x},${p.y} L${b[0]},${b[1]} L${a[0]+ww*.72},${a[1]-jag} L${a[0]+ww*.52},${a[1]+jag*.4} L${a[0]+ww*.3},${a[1]-jag*.85}Z" fill="#fff"/>`}
    if((o.sw??4)>0){const a=fl(.03,true),b=fl(.03,false);body+=`<path d="M${a[0]},${a[1]} Q${p.x-hw*.42+(a[0]-(p.x-hw))*0},${base-ph*.32} ${p.x},${p.y} Q${p.x+hw*.42},${base-ph*.32} ${b[0]},${b[1]}" fill="none" stroke="${mix(p.c,.45)}" stroke-width="${o.sw??4}" stroke-linecap="round" stroke-linejoin="round"/>`}});
  const sends=pk.filter(p=>!p.p),mx=sends.reduce((b,p)=>!b||lvl(p.g)>lvl(b.g)?p:b,null);
  if(mx&&o.flag!==false){const fs=o.fs||30,fw=mx.g.length*fs*.66+fs*1.3,fh=fs*1.55;body+=`<g transform="translate(${mx.x-fw/2},${mx.y-fh-14})"><rect width="${fw}" height="${fh}" rx="${fh/2}" fill="${mx.c}"/><text x="${fw/2}" y="${fh*.7}" text-anchor="middle" font-family="ID" font-weight="800" font-size="${fs}" fill="#fff">${mx.g}</text></g>`}
  if(o.baseLine!==false)body+=`<line x1="0" x2="${w}" y1="${base}" y2="${base}" stroke="${o.light?'#0000001a':'#ffffff1f'}" stroke-width="2"/>`;
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="display:block;overflow:visible"><defs>${defs}</defs>${body}</svg>`;
}
const AVG={sunset:'linear-gradient(180deg,#FFC94A,#FF5FA2 45%,#5A63D8 75%,#24224A)',sea:'linear-gradient(180deg,#9EE6FF,#3C8DFF 50%,#1C2F6B)',lime:'linear-gradient(180deg,#E8FF7A,#3DB36B 60%,#173F2A)',rose:'linear-gradient(180deg,#FFD3C2,#F07A5A 55%,#7A2B3A)',night:'linear-gradient(180deg,#2B2A5A,#6A3B8A 60%,#E57A8A)'};
const av=(s,g,ring='#8B5CF6',pct=.75)=>`<div class="av" style="width:${s}px;height:${s}px"><svg width="${s}" height="${s}" style="position:absolute;inset:0;transform:rotate(-90deg)"><circle cx="${s/2}" cy="${s/2}" r="${s/2-4}" fill="none" stroke="${ring}33" stroke-width="7"/><circle cx="${s/2}" cy="${s/2}" r="${s/2-4}" fill="none" stroke="${ring}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${(s-8)*Math.PI*pct} 999"/></svg><div style="position:absolute;inset:${s*.12}px;border-radius:50%;background:${AVG[g]}"></div></div>`;
const S1=[{g:'5+',f:1},{g:'6A'},{g:'6A',f:1},{g:'6B'},{g:'6C',p:1},{g:'6A'},{g:'6B+'},{g:'6B'}];
const S2=[{g:'5+'},{g:'6A',f:1},{g:'6A+'},{g:'6B',f:1},{g:'6B+'},{g:'7A',p:1},{g:'6C'},{g:'6B+',f:1},{g:'6C+',p:1}];
function sessionCard(x,y,w,o={}){const L=o.list||S1,st=o.stats||[['6','#F4EFE7'],['2','#E8C23A'],['6B','#F08A3C']];
  return `<div class="card" style="left:${x}px;top:${y}px;width:${w}px;padding:40px 40px 36px">
  <div style="display:flex;align-items:center;gap:26px">${av(110,o.av||'sunset',o.ring||'#8B5CF6')}<div style="flex:1"><div style="display:flex;align-items:center;gap:16px;font:700 40px ID;letter-spacing:-.02em">${o.name||'Marta G.'}<span class="pill" style="font-size:24px;padding:6px 14px;background:${(o.ring||'#8B5CF6')}2e;color:${o.ring||'#A98BFF'}">Nv ${o.lv||12}</span></div><div style="font:500 30px I;opacity:.55;margin-top:6px">${o.when||'martes'}</div></div><span class="pill" style="background:#3A2E22;color:#F2B44A;font-size:28px">◠ ${o.feel||'Bien'}</span></div>
  <div style="font:500 30px I;opacity:.55;margin:24px 0 0 6px">▥ ${o.gym||'Tu rocódromo'}</div>
  <div style="margin:10px -40px 0">${ridge(L,w,o.rh||250,{pad:80,padR:190})}</div>
  <div style="display:grid;grid-template-columns:repeat(3,1fr);margin-top:26px">${['TOPS','FLASH','MÁX'].map((l,i)=>`<div style="${i?'border-left:2px solid #ffffff14;padding-left:30px':''}"><div class="lbl">${l}</div><div style="font:800 68px ID;letter-spacing:-.03em;color:${st[i][1]};margin-top:2px">${st[i][0]}</div></div>`).join('')}</div>
  
  <div style="display:flex;justify-content:space-between;align-items:center;margin-top:24px"><div style="display:flex;gap:16px;align-items:center"><span class="pill" style="background:#3A311C;color:#F2C94C">+${o.xp||120} XP</span><span style="font:500 30px I;opacity:.55">◷ ${o.time||'1 h 32 min'}</span></div><div style="display:flex;gap:16px"><span class="pill" style="background:#2E2D31;color:#cfcac3">▢ ${o.c||3}</span><span class="pill" style="background:#2E2D31;color:#cfcac3">♦ ${o.k||17}</span></div></div></div>`}
function gradeGrid(x,y,w,light){const G=['4','5','5+','6A','6A+','6B','6B+','6C','6C+','7A','7A+','7B'],C={'5+':2,'6A':3,'6B':2,'6B+':1},gap=18,tw=(w-gap*3)/4;
  return `<div style="position:absolute;left:${x}px;top:${y}px;width:${w}px;display:grid;grid-template-columns:repeat(4,1fr);gap:${gap+6}px ${gap}px;z-index:4">${G.map(g=>`<div class="tile" style="height:${tw*.62}px;${light?'background:#fff;color:#161416;box-shadow:0 10px 30px -18px rgba(0,0,0,.35)':''};box-shadow:inset 0 -9px 0 ${GC[g]}${light?',0 10px 30px -18px rgba(0,0,0,.35)':''}">${g}${C[g]?`<span class="cnt" style="background:${GC[g]}">×${C[g]}</span>`:''}</div>`).join('')}</div>`}
function typeRow(x,y,w,sel='Top'){const T=[['Flash','ϟ','#3A311C','#F2C94C'],['Top','✓','#2E8B57','#fff'],['Proyecto','◌','#26304A','#7FA8FF']];
  return `<div style="position:absolute;left:${x}px;top:${y}px;width:${w}px;display:grid;grid-template-columns:repeat(3,1fr);gap:18px;z-index:4">${T.map(([t,i,b,c])=>`<div style="height:120px;border-radius:26px;background:${t===sel?(t==='Top'?'#34C759':b):'#2E2D31'};color:${t===sel?'#fff':c};display:grid;place-items:center;font:800 34px ID;text-align:center;line-height:1.1">${i}<br>${t}</div>`).join('')}</div>`}
function shareBg(kind,w,h){
  if(kind==='topo'){let l='';for(let i=0;i<14;i++){const cx=w*(.3+(i%3)*.25),cy=h*(.25+(i%4)*.18);for(let r=1;r<6;r++)l+=`<ellipse cx="${cx}" cy="${cy}" rx="${r*w*.07+i*3}" ry="${r*w*.05+i*2}" transform="rotate(${i*23} ${cx} ${cy})" fill="none" stroke="#EE888B" stroke-opacity=".35" stroke-width="2"/>`}
    return {css:'background:#F6EFE4',svg:`<svg width="${w}" height="${h}" style="position:absolute;inset:0">${l}</svg>`,ink:'#1E1C1A'}}
  if(kind==='grano')return {css:'background:linear-gradient(170deg,#FFB36B,#F0607A 50%,#7E3FA0)',svg:`<svg width="${w}" height="${h}" style="position:absolute;inset:0;opacity:.35;mix-blend-mode:overlay"><filter id="gn${w}"><feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="2"/></filter><rect width="100%" height="100%" filter="url(#gn${w})"/></svg>`,ink:'#fff'};
  if(kind==='foto')return {css:'background:#3a3a3a',svg:`<img src="${PHOTO}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover"><div style="position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.35),rgba(0,0,0,0) 30%,rgba(0,0,0,0) 45%,rgba(0,0,0,.75))"></div>`,ink:'#fff'};
  // cordillera: layered sunset ranges, like the app background
  const L=[['#F7B267',.30],['#E9787A',.42],['#B0568A',.54],['#7A4492',.66],['#4A2F78',.78]];let r='';
  L.forEach(([c,y],i)=>{let d=`M0,${h} L0,${h*y}`;for(let k=0;k<=8;k++){d+=` L${w*k/8},${h*y-((k*37+i*53)%5)*h*.018-(k%2?h*.03:0)}`}d+=` L${w},${h}Z`;r+=`<path d="${d}" fill="${c}"/>`});
  return {css:'background:linear-gradient(180deg,#FFC98A,#F59A7A 30%,#C76A8A)',svg:`<svg width="${w}" height="${h}" style="position:absolute;inset:0"><circle cx="${w*.68}" cy="${h*.2}" r="${w*.1}" fill="#FFE2B8"/>${r}</svg>`,ink:'#fff'};
}
function shareCard(x,y,w,rot=4,kind='cordillera',o={}){const h=w*1.62,B=shareBg(kind,w,h),ink=B.ink;return `<div style="position:absolute;left:${x}px;top:${y}px;width:${w}px;height:${h}px;border-radius:${w*.13}px;overflow:hidden;transform:rotate(${rot}deg);${B.css};box-shadow:0 60px 120px -40px #000;z-index:4">${B.svg}
  <div style="position:absolute;left:${w*.09}px;top:${w*.1}px;display:flex;align-items:center;gap:${w*.04}px;color:${ink};font:800 ${w*.055}px ID">${LOGO(w*.05)}kumbra</div>
  <div style="position:absolute;left:${w*.09}px;right:${w*.09}px;top:${h*.6}px;color:${ink}"><div style="font:700 ${w*.07}px ID">${o.name||'Marta G.'}</div><div style="font:500 ${w*.04}px I;opacity:.75">${o.place||'Tu rocódromo · martes'}</div></div>
  <div style="position:absolute;left:0;right:0;top:${h*.7}px">${ridge(S1,w,h*.13,{pad:w*.09,grid:false,fs:w*.05,sw:2.5,light:kind==='topo',baseLine:false})}</div>
  <div style="position:absolute;left:${w*.09}px;right:${w*.09}px;top:${h*.85}px;display:flex;gap:${w*.11}px;color:${ink}">${[['TOPS','6',ink],['FLASH','2',kind==='topo'?'#C99A10':'#F2C94C'],['MÁX','6B',kind==='topo'?'#EE888B':'#FFB36B']].map(([l,v,c])=>`<div><div style="font:700 ${w*.035}px I;letter-spacing:.1em;opacity:.75">${l}</div><div style="font:800 ${w*.11}px/1 ID;color:${c}">${v}</div></div>`).join('')}</div></div>`}
function standings(x,y,w,o={}){const R=o.rows||[['Lucía','sea','#3C8DFF',11],['Tú','sunset','#EE888B',10],['Dani','lime','#3DB36B',7],['Marta','rose','#F07A5A',5]];const mx=Math.max(...R.map(r=>r[3]));
  return `<div class="card" style="left:${x}px;top:${y}px;width:${w}px;padding:44px">
  <div style="display:flex;justify-content:space-between;align-items:baseline"><b style="font:800 44px ID;letter-spacing:-.02em">${o.title||'Más días escalando'}</b><span style="font:700 28px I;color:#EE888B">${o.left||'Quedan 3 días'}</span></div>
  <div style="font:500 28px I;opacity:.5;margin-top:8px">${o.sub||'Reto de Lucía · 1 mes'}</div>
  <div style="display:grid;gap:26px;margin-top:36px">${R.map((r,i)=>`<div style="display:grid;grid-template-columns:40px 80px 1fr 60px;align-items:center;gap:20px;font:800 36px ID"><span style="opacity:.4">${i+1}</span>${av(80,r[1],r[2],1)}<div><div style="font:700 30px I;margin-bottom:10px;${r[0]==='Tú'?'color:#EE888B':''}">${r[0]}</div><div style="height:14px;border-radius:7px;background:#ffffff14"><div style="height:100%;width:${r[3]/mx*100}%;border-radius:7px;background:${r[2]}"></div></div></div><span style="text-align:right">${r[3]}</span></div>`).join('')}</div></div>`}
function medal(g,label,sub,s=230){const c=GC[g]||g;return `<div style="display:flex;flex-direction:column;align-items:center;gap:18px;width:${s+40}px;text-align:center"><div style="width:${s}px;height:${s}px;border-radius:50%;background:radial-gradient(circle at 50% 35%,${mix(c,.35)},${c} 60%,${mix(c,.45,10)});box-shadow:inset 0 0 0 10px #ffffff33,0 30px 60px -25px ${c};display:grid;place-items:center;font:900 ${s*.32}px ID;color:#fff;letter-spacing:-.03em">${label}</div><div style="font:700 30px ID;letter-spacing:-.01em">${sub}</div></div>`}
function weeks(x,y,w){const W=[['24/8',0],['31/8',1],['7/9',1],['14/9',1],['21/9',1],['28/9',1],['5/10',2]];
  return `<div class="card" style="left:${x}px;top:${y}px;width:${w}px;padding:44px"><div class="lbl" style="opacity:.6">Racha</div><div style="display:flex;align-items:baseline;gap:18px;margin-top:10px"><b style="font:900 150px/1 ID;color:#EE888B;letter-spacing:-.04em">6</b><span style="font:600 40px I;opacity:.7">semanas seguidas</span></div>
  <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-top:34px;text-align:center">${W.map(([d,s])=>`<div><div style="font:600 24px I;opacity:.5;margin-bottom:14px">${d}</div><div style="width:76px;height:76px;margin:auto;border-radius:50%;display:grid;place-items:center;font:800 34px I;${s===0?'background:#2E2D31;color:#77727a':s===1?'background:#1F3A2A;color:#4ED17F':'background:#EE888B;color:#fff'}">${s===0?'×':'✓'}</div></div>`).join('')}</div></div>`}
function levelCard(x,y,w){return `<div class="card" style="left:${x}px;top:${y}px;width:${w}px;padding:48px;display:flex;gap:44px;align-items:center">${av(200,'sunset','#A06BFF',.8)}<div><div style="font:800 30px I;letter-spacing:.06em;color:#A98BFF">CRUSHER</div><div style="font:900 84px/1 ID;letter-spacing:-.04em;margin:10px 0">Nivel 12</div><div style="font:500 30px I;opacity:.55">280 XP para el nivel 13</div></div></div>`}
function ridgesDeco(light){const L=[{g:'5'},{g:'6A',f:1},{g:'6B'},{g:'6A+'},{g:'6C'},{g:'7A',f:1},{g:'6B+'},{g:'6A'},{g:'6B',f:1},{g:'5+'}];return `<div style="position:absolute;left:-60px;right:-60px;bottom:0;z-index:1">${ridge(L,1200,360,{grid:false,flag:false,pad:30,top:20,sw:5,light,baseLine:false})}</div>`}
const CTA=()=>V==='pre'?{b:'Reserva tu @',s:'Antes del lanzamiento · enlace en la bio'}:{b:'Descárgala',s:'Gratis · iPhone y Android · enlace en la bio'};

const PHOTO=Q.get('photo')||'';
function notifs(x,y,w){const N=[['lime','#3DB36B','Dani','te ha dado kudos en tu 6C','ahora'],['sea','#3C8DFF','Lucía','ha encadenado su primer 7A','hace 12 min'],['rose','#F07A5A','Marta','te reta: más días en octubre','hace 1 h'],['night','#8B5CF6','Pablo','ha empezado una sesión','hace 2 h']];
  return `<div style="position:absolute;left:${x}px;top:${y}px;width:${w}px;display:grid;gap:22px;z-index:4">${N.map(([g,c,n,t,when],i)=>`<div style="background:#232225;border-radius:40px;padding:30px 34px;display:flex;align-items:center;gap:26px;opacity:${1-i*.16};transform:scale(${1-i*.03});box-shadow:0 30px 60px -30px #000">${av(96,g,c,1)}<div style="flex:1;font:500 34px/1.3 I"><b style="font-weight:700">${n}</b> ${t}<div style="font:500 26px I;opacity:.5;margin-top:4px">${when}</div></div></div>`).join('')}</div>`}
function bigTiles(){const T=[['6A',360,'-8'],['6B+',300,'4'],['6C',250,'-3']];return T.map(([g,sz,r],i)=>`<div class="tile" style="position:absolute;right:${80+i*230}px;bottom:${120+i*150}px;width:${sz}px;height:${sz*.62}px;font-size:${sz*.26}px;transform:rotate(${r}deg);box-shadow:inset 0 -${sz*.05}px 0 ${GC[g]},0 40px 80px -30px #000;z-index:3">${g}</div>`).join('')}
function shareSheet(x,y){const th=[['Grano','grano'],['Cordillera','cordillera'],['Topo','topo']];
  return `${shareCard(x+292,y,320,0,'grano')}<div style="position:absolute;left:88px;right:88px;top:${y+560}px;display:flex;gap:22px;justify-content:center;z-index:4">${th.map(([n,k],i)=>`<div style="text-align:center"><div style="width:132px;height:176px;border-radius:24px;overflow:hidden;position:relative;${shareBg(k,132,176).css};${i===0?'box-shadow:0 0 0 6px #EE888B':''}">${shareBg(k,132,176).svg}</div><div style="font:600 26px I;margin-top:14px;${i===0?'color:#EE888B':'opacity:.6'}">${n}</div></div>`).join('')}${['Foto','Vídeo'].map(n=>`<div style="text-align:center"><div style="width:132px;height:176px;border-radius:24px;background:#2E2D31;display:grid;place-items:center;font:700 44px I;opacity:.8">${n==='Foto'?'▣':'▶'}</div><div style="font:600 26px I;margin-top:14px;opacity:.6">${n}</div></div>`).join('')}</div>`}

function ascending(left=40,bottom=0,w=1000,h=500){const C=['#3DB36B','#E8C23A','#F08A3C','#E5484D','#D0479A','#8B5CF6','#5B6CF0'],n=C.length,sp=w/(n+.2),hw=sp*.95;let defs='',b='';
  C.forEach((c,i)=>{const x=sp*(i+.6),ph=h*(.3+.7*i/(n-1)),y=h-ph,id='as'+i;defs+=`<linearGradient id="${id}" x1="0" y1="${y}" x2="0" y2="${h}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="${c}" stop-opacity=".55"/></linearGradient>`;
    b+=`<path d="M${x-hw},${h} Q${x-hw*.3},${h-ph*.35} ${x},${y} Q${x+hw*.3},${h-ph*.35} ${x+hw},${h}Z" fill="url(#${id})" opacity=".95"/>`;
    if(i===n-1){const d=ph*.13;b+=`<path d="M${x-d*.28},${y+d} L${x},${y} L${x+d*.28},${y+d} L${x+d*.1},${y+d*.8} L${x},${y+d*1.1} L${x-d*.12},${y+d*.78}Z" fill="#fff"/>`}});
  return `<svg width="${w}" height="${h}" style="position:absolute;left:${left}px;bottom:${bottom}px;z-index:1;overflow:visible"><defs>${defs}</defs>${b}</svg>`}
