function tierAv(k,s){const r=s/2;const inner={
 novato:`<circle cx="${r}" cy="${r}" r="${r*.78}" fill="#A0522D"/><path d="M${r*.45},${r*1.55} L${r*1.4},${r*.4} M${r*.65},${r*1.7} L${r*1.6},${r*.6}" stroke="#2B1A10" stroke-width="${s*.04}"/>`,
 escalador:`<circle cx="${r}" cy="${r}" r="${r*.78}" fill="#2F4374"/><ellipse cx="${r*.7}" cy="${r*.6}" rx="${r*.18}" ry="${r*.12}" fill="#9AA0A8"/><ellipse cx="${r*1.4}" cy="${r*1.35}" rx="${r*.2}" ry="${r*.14}" fill="#9AA0A8"/><circle cx="${r*1.3}" cy="${r*.55}" r="${s*.015}" fill="#fff"/>`,
 crusher:`<defs><linearGradient id="tc${s}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFC94A"/><stop offset=".45" stop-color="#FF5FA2"/><stop offset=".75" stop-color="#5A63D8"/><stop offset="1" stop-color="#24224A"/></linearGradient></defs><circle cx="${r}" cy="${r}" r="${r*.78}" fill="url(#tc${s})"/>`,
 pro:`<circle cx="${r}" cy="${r}" r="${r*.78}" fill="#9FB0B0"/><path d="M${r*.45},${r*1.2} L${r*.55},${r*.7} L${r*1.0},${r*.75} L${r*1.55},${r*1.15} L${r*1.5},${r*1.35} L${r*.5},${r*1.35}Z" fill="#B8622D"/><circle cx="${r*.85}" cy="${r*.95}" r="${s*.02}" fill="#2B1A10"/><circle cx="${r*1.05}" cy="${r*.98}" r="${s*.02}" fill="#2B1A10"/>`,
 leyenda:`<circle cx="${r}" cy="${r}" r="${r*.78}" fill="#1E2240"/><path d="M${r*.35},${r*1.5} Q${r*.8},${r*1.15} ${r},${r*.85} Q${r*1.2},${r*1.15} ${r*1.65},${r*1.5}Z" fill="#B03A7A"/><path d="M${r*.88},${r*1.0} L${r},${r*.85} L${r*1.12},${r*1.0}Z" fill="#fff"/><circle cx="${r*.6}" cy="${r*.6}" r="${s*.012}" fill="#F2C94C"/><circle cx="${r*1.35}" cy="${r*.5}" r="${s*.012}" fill="#F2C94C"/>`}[k];
 const ring={novato:'#2E8B3F',escalador:'#2F5FAF',crusher:'#A06BFF',pro:'#B5502A',leyenda:'#A68A2A'}[k];
 return `<svg width="${s}" height="${s}"><circle cx="${r}" cy="${r}" r="${r-s*.03}" fill="none" stroke="${ring}" stroke-width="${s*.05}"/><circle cx="${r}" cy="${r}" r="${r*.84}" fill="#1a191c"/>${inner}</svg>`}
