function bigPeak(c,snow,ghost){const w=720,h=370,x=w/2,hw=310,base=h,y=20,ph=base-y;const fl=(t,l)=>{const sx=l?x-hw:x+hw,cx=l?x-hw*.42:x+hw*.42,cy=base-ph*.32,u=1-t;return [u*u*sx+2*u*t*cx+t*t*x,u*u*base+2*u*t*cy+t*t*y]};
 const d=`M${x-hw},${base} Q${x-hw*.42},${base-ph*.32} ${x},${y} Q${x+hw*.42},${base-ph*.32} ${x+hw},${base}`;let b='';
 if(ghost)b=`<path d="${d}Z" fill="${c}" opacity=".22"/>`;else{b=`<defs><linearGradient id="bp${c.slice(1)}" x1="0" y1="${y}" x2="0" y2="${base}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="${mix(c,.38,20)}"/></linearGradient></defs><path d="${d}Z" fill="url(#bp${c.slice(1)})"/>`;
  if(snow){const dp=ph*.26,t=1-dp/ph,a=fl(t,1),bb=fl(t,0),ww=bb[0]-a[0],j=dp*.25;b+=`<path d="M${a[0]},${a[1]} L${x},${y} L${bb[0]},${bb[1]} L${a[0]+ww*.72},${a[1]-j} L${a[0]+ww*.52},${a[1]+j*.4} L${a[0]+ww*.3},${a[1]-j*.85}Z" fill="#fff"/>`}
  b+=`<path d="${d}" fill="none" stroke="${mix(c,.45)}" stroke-width="7" stroke-linecap="round"/>`}
 return `<svg width="${w}" height="${h}" style="position:absolute;left:${(1080-w)/2}px;bottom:-4px;z-index:2;overflow:visible">${b}</svg>`}

