   <div style="position:absolute;left:88px;right:88px;top:76px;display:flex;justify-content:space-between;align-items:center;z-index:5;color:${fg}"><div style="display:flex;align-items:center;gap:16px;font:800 38px ID;letter-spacing:-.025em">${LOGO(44)}kumbra</div><span style="font:600 30px I;opacity:.7">${n}</span></div>
