function live(x,y,w){return `<div class="card" style="left:${x}px;top:${y}px;width:${w}px;padding:44px">
  <div style="display:flex;justify-content:space-between;align-items:center"><span class="pill" style="background:#3A2030;color:#EE888B;font-size:26px">● Sesión en curso</span><span style="font:600 28px I;opacity:.55">Tu rocódromo</span></div>
  <div style="font:900 150px/1 ID;letter-spacing:-.04em;margin:30px 0 6px;font-variant-numeric:tabular-nums">0:42:10</div><div style="font:500 32px I;opacity:.55">5 bloques · 2 flash</div>
  <div style="margin:26px -44px 0">${ridge([{g:'5+',f:1},{g:'6A'},{g:'6A+',f:1},{g:'6B'},{g:'6B+',p:1}],w,200,{pad:80,grid:false})}</div>
  <div style="margin-top:30px;height:110px;border-radius:30px;background:linear-gradient(95deg,#F2B44A,#E5484D 50%,#A7377B);color:#fff;display:grid;place-items:center;font:800 40px ID">+ Añadir bloque</div></div>`}
